raw:
{
  "spells": [
    {
      "id": "spell_shadow_07",
      "theory": "暗刺术把魔力压入随身暗色媒介，如黑布、炭块或深色皮面，媒介中的魔力沿一条极细的暗色轨迹凝成短刺。刺的形态由媒介纹理决定，布面出刺较软，石面出刺较硬。刺体离开媒介后无法自行维持，穿过强光时轨迹迅速衰减，最终化为无害的暗尘。它只造成穿刺伤害，不带来恐惧、诅咒或持续流血。",
      "casting": "一手握紧暗色媒介，另一手食指与中指并拢，沿刺出方向划一道短直痕，同时将魔力从掌心压入媒介纹理。划痕完成时松指，暗刺即刻射出。",
      "failure": "魔力未能沿单一纹理凝聚，暗刺会在掌前半尺处散成暗尘，或歪斜飞出数尺后无力坠落。失败时媒介表面留下焦痕，需重新准备。强光下失败概率更高。",
      "counters": [
        "举起反光金属板迎向暗刺，强光会加速暗刺衰减。",
        "用厚实织物多层覆盖身体，可挡住残余暗刺的穿刺。"
      ],
      "socialConsequences": "河谷乡约允许在自卫或狩猎时公开使用，但若在集市朝人施放，会被视为斗殴并追究伤情。城市公会要求施术前确认周围无无辜者，持许可者可在指定训练场练习。琥珀海岸港务对船上使用格外警惕，货主担心暗刺损坏帆布或缆绳，水手则欣赏它能切断缠住船桨的旧绳。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度：暗刺轨迹明显弯曲，常只擦过目标表面。",
        "中熟练度：能稳定命中十步内静止目标，衰减距离不变。",
        "高熟练度：可控制刺出角度，减少对周围器物的误伤。",
        "极高熟练度：在强光下也能保持刺形，但射程仍为十米。"
      ]
    },
    {
      "id": "spell_shadow_08",
      "theory": "契痕审读将魔力送入一份魔法契约的墨迹或刻痕，使被改动过的符文线条浮现出暗色重影。重影只标出修改位置，不显示修改者身份，也不判断修改是否合法。契约可以是羊皮纸、石板或木片，但必须包含至少一处魔力刻写。未受魔的普通字迹无法被审读。",
      "casting": "双手托住契约，指尖轻触纸面或石面，闭眼默数三息，然后将魔力沿契约边缘缓缓推入。睁眼时，被改动的符文会呈现暗色重影，持续约一分钟。",
      "failure": "魔力在契约表面滑开，重影无法成形，或只在一两个符文上闪出模糊暗斑。若契约本身魔力微弱，审读可能误将旧墨迹当成修改痕迹，给出不准确的提示。",
      "counters": [
        "将契约置于强光下，重影会变淡，但仍能看出大致位置。",
        "用自身魔力覆盖契约表面，可暂时干扰审读，但会留下痕迹。"
      ],
      "socialConsequences": "河谷常由乡约见证民事承诺，审读结果可作为调解参考，但乡约不据此定罪。城市公会要求审读师在双方同意下操作，擅自审读他人契约会被投诉。琥珀海岸港务对航运合同审读需求大，货主与船主都希望确认条款未被篡改，但审读师若泄露内容会失去信誉。",
      "law": {
        "river": "consent",
        "city": "consent",
        "port": "consent"
      },
      "proficiencyEffects": [
        "低熟练度：重影模糊，只能指出大概位置，容易误判。",
        "中熟练度：能清晰标出改动符文，但无法区分新旧墨迹。",
        "高熟练度：可分辨修改发生在契约成立前后，减少误读。",
        "极高熟练度：能同时审读多页契约，重影位置依然准确。"
      ]
    },
    {
      "id": "spell_shadow_09",
      "theory": "夜视匣取一小块树脂，以魔力将其内部气泡排列成暗色晶格，再将晶格覆于受术者眼睑外。晶格会汇聚微光，使人在月光、星光或烛火下辨物更清。它不产生光线，完全无光时仍无法视物。树脂是媒介，晶格悬浮在眼睑外，不接触眼球，也不改变眼睛本身。",
      "casting": "将树脂捏在拇指与食指间，对着受术者眉心画一个空心圆，同时把魔力注入树脂。树脂化为暗色薄片，自动贴合受术者眼睑。持续九十秒后薄片消散。",
      "failure": "树脂在指尖碎裂，薄片无法成形，受术者只感到短暂凉意。若魔力注入过快，薄片会覆盖过厚，视野反而变暗，且提前脱落。失败时树脂不可回收。",
      "counters": [
        "用不透光的眼罩遮住眼睛，薄片便无法汇聚微光。",
        "以清水冲洗眼部，可提前冲落薄片，使效果中断。"
      ],
      "socialConsequences": "河谷夜巡者常请人施放此术，以便在不举火把的情况下巡视田界。城市公会允许公开使用，但要求施术者不得借此窥探他人院内。琥珀海岸港务提醒夜间装卸工，薄片不能替代灯火信号，船主担心有人依赖此术而忽略航标。树脂商因此术销量略增。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度：薄片贴合不匀，视野边缘仍模糊，持续稍短。",
        "中熟练度：能在微光下稳定辨物，薄片不再提前脱落。",
        "高熟练度：可调整薄片透光，减轻强光下的刺眼感。",
        "极高熟练度：薄片几乎不可见，但完全无光时仍无效。"
      ]
    }
  ]
}
